        }
    }

    pub fn to_upper(&self, s: string) -> string {
        if s in self.cache {
            return self.cache[s];
        }

        let result = "";
        let i = 0;

        while i < length(s) {
            let ch = s[i];

            if ch >= "a" && ch <= "z" {
                result = result + ((ch as i32) - 32 as string);
            } else {
                result = result + ch;
            }

            i = i + 1;
        }

        result
    }

    pub fn to_lower(&self, s: string) -> string {
        let result = "";
        let i = 0;

        while i < length(s) {
            let ch = s[i];

            if ch >= "A" && ch <= "Z" {
                result = result + ((ch as i32) + 32 as string);
            } else {
                result = result + ch;
            }

            i = i + 1;
        }

        result
    }

    pub fn trim(&self, s: string) -> string {
        let mut start = 0;
        let mut end = length(s);

        while start < end && (s[start] == " " || s[start] == "\t" || s[start] == "\n") {
            start = start + 1;
        }

        while end > start && (s[end - 1] == " " || s[end - 1] == "\t" || s[end - 1] == "\n") {
            end = end - 1;
        }

        if start >= end { "" } else { s[start..end] }
    }

    pub fn split(&self, s: string, delimiter: string) -> any {
        let parts = [];
        let current = "";
        let i = 0;

        while i < length(s) {
            if s[i] == delimiter {
                push(parts, current);
                current = "";
            } else {
                current = current + s[i];
            }

            i = i + 1;
        }

        push(parts, current);
        parts
    }

    pub fn join(&self, arr: any, delimiter: string) -> string {
        let result = "";
        let i = 0;

        while i < length(arr) {
            result = result + arr[i];

            if i < length(arr) - 1 {
                result = result + delimiter;
            }

            i = i + 1;
        }

        result
    }

    pub fn contains(&self, s: string, substr: string) -> bool {
        let i = 0;

        while i <= length(s) - length(substr) {
            let match = true;
            let j = 0;

            while j < length(substr) {
                if s[i + j] != substr[j] {
                    match = false;
                    break;
                }
                j = j + 1;
            }

            if match {
                return true;
            }

            i = i + 1;
        }

        false
    }

    pub fn replace(&self, s: string, from: string, to: string) -> string {
        let result = "";
        let i = 0;

        while i < length(s) {
            if i + length(from) <= length(s) {
                let substring = s[i..i + length(from)];
                if substring == from {
                    result = result + to;
                    i = i + length(from);
                    continue;
                }
            }

            result = result + s[i];
            i = i + 1;
        }

        result
    }
}

